#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int findSubstringInWraproundString(char* s) {
    int best[26] = {0};
    int run = 0;
    int ans = 0;
    int n = (int)strlen(s);

    for (int i = 0; i < n; ++i) {
        if (i > 0 && ((s[i] - s[i - 1] + 26) % 26) != 1) {
            run = 0;
        }
        ++run;
        int idx = s[i] - 'a';
        if (run > best[idx]) {
            ans += run - best[idx];
            best[idx] = run;
        }
    }
    return ans;
}

