    const best = new Array(26).fill(0);
    let run = 0;
    let ans = 0;

    for (let i = 0; i < s.length; i++) {
        if (i > 0 && ((s.charCodeAt(i) - s.charCodeAt(i - 1) + 26) % 26) !== 1) {
            run = 0;
        }
